//! Persisted, directly executable local operations for the P4 conversation UI.
use crate::{Shared, Res, locked, core::{self, Edit}, transport::AppHandle};
use serde::{Serialize, Deserialize};
use serde_json::{Value,json};
use std::{path::{Path,PathBuf},collections::HashSet,sync::{Mutex,OnceLock,atomic::{AtomicBool,Ordering}},io::Write};
use sha2::{Sha256,Digest};

fn now()->u64{std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_millis() as u64}
#[derive(Clone,Serialize,Deserialize)]#[serde(rename_all="camelCase")]
struct Snapshot{base:Option<String>,edit:Edit,trashed:bool}
impl Snapshot{fn of(a:&core::Asset)->Self{Self{base:a.generated_base.clone(),edit:a.edit.clone(),trashed:a.trashed}}}
#[derive(Clone,Serialize,Deserialize)]#[serde(rename_all="camelCase")]
struct Item{id:String,before:Snapshot,after:Option<Snapshot>,state:String,error:Option<String>}
#[derive(Clone,Serialize,Deserialize)]#[serde(rename_all="camelCase")]
struct Job{id:String,project_id:String,request_hash:String,operations:Vec<Value>,items:Vec<Item>,state:String,created_at:u64,started_at:Option<u64>,updated_at:u64,host:bool,undone:bool}
fn directory(s:&Shared)->Res<PathBuf>{let path=locked(s)?.root.join("operation-jobs");std::fs::create_dir_all(&path).map_err(|e|e.to_string())?;Ok(path)}
fn path(root:&Path,id:&str)->Res<PathBuf>{uuid::Uuid::parse_str(id).map_err(|_|"INVALID_TASK_ID")?;Ok(root.join(format!("{id}.json")))}
/// A Windows reader may briefly deny delete-sharing during atomic replacement.
/// Keep the same complete temporary file and retry only these transient OS errors.
pub(crate) fn persist_temp(mut file:tempfile::NamedTempFile,target:PathBuf)->Res<()>{
 for attempt in 0..7{match file.persist(&target){Ok(_)=>return Ok(()),Err(error)=>{
  if cfg!(windows)&&matches!(error.error.raw_os_error(),Some(5|32|33))&&attempt<6{file=error.file;std::thread::sleep(std::time::Duration::from_millis(5u64<<attempt));}else{return Err(error.error.to_string())}
 }}}Err("TASK_STORAGE_UNAVAILABLE".into())
}
fn save(root:&Path,job:&Job)->Res<()>{let mut file=tempfile::NamedTempFile::new_in(root).map_err(|e|e.to_string())?;file.write_all(&serde_json::to_vec(job).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;file.as_file().sync_all().map_err(|e|e.to_string())?;persist_temp(file,path(root,&job.id)?)}
fn read(root:&Path,id:&str)->Res<Job>{serde_json::from_slice(&std::fs::read(path(root,id)?).map_err(|_|"TASK_NOT_FOUND")?).map_err(|_|"TASK_CORRUPT".into())}
fn jobs(root:&Path)->Vec<Job>{std::fs::read_dir(root).into_iter().flatten().flatten().filter(|e|e.path().extension().is_some_and(|ext|ext=="json")&&e.path().file_stem().and_then(|name|name.to_str()).is_some_and(|name|uuid::Uuid::parse_str(name).is_ok())).filter_map(|e|std::fs::read(e.path()).ok()).filter_map(|b|serde_json::from_slice(&b).ok()).collect()}
pub(crate) fn planning(s:&Shared,id:&str)->Res<PathBuf>{let root=directory(s)?;path(&root,id)?;if root.join(format!("{id}.planning")).exists(){return Err("PLANNING_IN_PROGRESS".into())}std::fs::write(root.join(format!("{id}.planning")),b"planning").map_err(|e|e.to_string())?;Ok(root)}
pub(crate) fn planning_context(s:&Shared,id:&str,pid:&str,context:&Value)->Res<PathBuf>{let root=planning(s,id)?;atomic_value(&root,&format!("{id}.planning"),&json!({"projectId":pid,"assetIds":context["resolvedTarget"]["ids"],"state":"planning"}))?;Ok(root)}
pub(crate) fn existing(s:&Shared,id:&str)->Res<Option<Value>>{let root=directory(s)?;let path=path(&root,id)?;Ok(if path.exists(){Some(task_view(&root,&read(&root,id)?))}else{None})}
fn terminal(state:&str)->bool{matches!(state,"done"|"partial"|"failed"|"cancelled")}
fn view(job:&Job)->Value{json!({"id":job.id,"type":"operation","undoable":!(job.operations.len()==1&&job.operations[0]["kind"]=="export"),"pipeline":job.operations.first().is_some_and(|op|op["kind"]=="pipeline"),"batchId":job.id,"projectId":job.project_id,"accountId":if job.host{"host"}else{"team"},"state":job.state,"targetCount":job.items.len(),"quotaUnits":if job.operations.iter().any(|op|matches!(op["kind"].as_str(),Some("restore"|"trash"|"undo"|"redo")))||job.operations.len()==1&&job.operations[0]["kind"]=="export"{0}else{job.items.iter().filter(|item|item.state=="done").count()},"assetIds":job.items.iter().map(|item|&item.id).collect::<Vec<_>>(),"done":job.items.iter().filter(|item|item.state=="done").count(),"failed":job.items.iter().filter(|item|matches!(item.state.as_str(),"failed"|"uncertain")).count(),"total":job.items.len(),"queuePosition":null,"startedAt":job.started_at,"updatedAt":job.updated_at,"undone":job.undone,"resultAssetIds":job.items.iter().filter(|item|item.state=="done").map(|item|&item.id).collect::<Vec<_>>(),"warnings":job.items.iter().filter(|item|item.state=="done").filter_map(|item|item.error.clone()).collect::<Vec<_>>(),"failures":job.items.iter().filter(|item|matches!(item.state.as_str(),"failed"|"uncertain")).filter_map(|item|item.error.as_ref().map(|error|json!({"assetId":item.id,"message":error}))).collect::<Vec<_>>(),"summary":job.operations.iter().filter_map(|op|if op["kind"]=="local_plan"{op["plan"]["summary"].as_str().or(Some("本地处理"))}else if op["kind"]=="pipeline"{op["pipeline"]["summary"].as_str().or(Some("混合处理"))}else{op["kind"].as_str()}).collect::<Vec<_>>().join(" → ")})}
fn task_view(root:&Path,job:&Job)->Value{let mut value=view(job);value["outputs"]=json!(crate::frontend_output::descriptors(root,&job.id));value}
pub(crate) fn list(s:&Shared)->Res<Vec<Value>>{let root=directory(s)?;let mut values=jobs(&root).iter().map(|job|task_view(&root,job)).collect::<Vec<_>>();if let Some(queue)=QUEUE.get().and_then(|q|q.lock().ok()){let mut pending=queue.pending.iter().collect::<Vec<_>>();pending.sort_by_key(|p|!p.host);for(index,p)in pending.iter().enumerate(){if p.root==root{if let Some(task)=values.iter_mut().find(|v|v["id"]==p.id){task["queuePosition"]=json!(index);}}}}Ok(values)}
pub(crate) fn stop(s:&Shared,id:&str)->Res<Value>{let root=directory(s)?;let mut job=match read(&root,id){Ok(job)=>job,Err(error)=>{path(&root,id)?;if root.join(format!("{id}.planning")).is_file(){std::fs::write(root.join(format!("{id}.cancel")),b"stop").map_err(|e|e.to_string())?;return Ok(json!({"id":id,"type":"operation","state":"cancelled","total":0,"done":0}))}return Err(error)}};if !terminal(&job.state){if job.operations[0]["kind"]=="pipeline"&&root.parent().unwrap().join("hybrid-jobs").join(id).join("job.json").is_file(){crate::hybrid::request_cancel(root.parent().unwrap(),id)?;}std::fs::write(root.join(format!("{id}.cancel")),b"stop").map_err(|e|e.to_string())?;if job.state=="queued"{job.state="cancelled".into();job.updated_at=now();save(&root,&job)?;}}Ok(view(&job))}

pub(crate) fn context_ids(s:&Shared,pid:&str,context:&Value,allow_empty:bool)->Res<Vec<String>>{
 let object=context.as_object().ok_or("SELECTION_CONTEXT_REQUIRED")?;
 let keys=["page","mentions","selected","editorAssetId","filter","filteredCount","resolvedTarget","fileNames"];
 if object.len()!=keys.len()||keys.iter().any(|key|!object.contains_key(*key))||!matches!(context["page"].as_str(),Some("home"|"library"|"editor")){return Err("INVALID_SELECTION_CONTEXT".into())}
 let filter=context["filter"].as_object().ok_or("INVALID_SELECTION_CONTEXT")?;let filter_keys=["folder","tag","status","q","sort"];if filter.len()!=5||filter.keys().any(|key|!filter_keys.contains(&key.as_str()))||filter.values().any(|value|!value.is_string())||context["filteredCount"].as_u64().is_none(){return Err("INVALID_SELECTION_CONTEXT".into())}
 let target=context["resolvedTarget"].as_object().ok_or("INVALID_SELECTION_CONTEXT")?;if target.len()!=2||!target.contains_key("source")||!target.contains_key("ids")||!(context["editorAssetId"].is_null()||context["editorAssetId"].is_string()){return Err("INVALID_SELECTION_CONTEXT".into())}
 let strings=|key:&str|->Res<Vec<String>>{context[key].as_array().ok_or("INVALID_SELECTION_CONTEXT")?.iter().map(|value|value.as_str().map(str::to_string).ok_or("INVALID_SELECTION_CONTEXT".into())).collect()};
 let mentions=strings("mentions")?;let selected=strings("selected")?;
 let ids=context["resolvedTarget"]["ids"].as_array().ok_or("INVALID_SELECTION_CONTEXT")?.iter().map(|v|v.as_str().map(str::to_string).ok_or("INVALID_SELECTION_CONTEXT".into())).collect::<Res<Vec<_>>>()?;
 let (source,expected)=if !mentions.is_empty(){("mention",mentions)}else if !selected.is_empty(){("selected",selected)}else if let Some(id)=context["editorAssetId"].as_str(){("editor",vec![id.into()])}else{("filter",ids.clone())};
 let mut seen=HashSet::new();let expected=expected.into_iter().filter(|id|seen.insert(id.clone())).collect::<Vec<_>>();
 if context["resolvedTarget"]["source"]!=source||expected!=ids||ids.len()>5000||(!allow_empty&&ids.is_empty()){return Err("INVALID_SCOPE".into())}
 let names=strings("fileNames")?;if names.len()!=ids.len()||names.iter().any(|name|name.contains(['/', '\\', ':'])){return Err("INVALID_FILENAMES".into())}
 let p=locked(s)?.load(pid)?;for(id,name)in ids.iter().zip(names){let a=p.assets.iter().find(|a|&a.id==id).ok_or("ASSET_NOT_FOUND")?;if a.name.rsplit(['/', '\\']).next()!=Some(name.as_str()){return Err("SELECTION_CHANGED".into())}}
 Ok(ids)
}
fn validate_operations(operations:&[Value])->Res<()>{
 if operations.is_empty()||operations.len()>20{return Err("INVALID_OPERATIONS".into())}
 for op in operations{let kind=op["kind"].as_str().ok_or("INVALID_OPERATION")?;let allowed=match kind{"fit_ratio"=>vec!["kind","ratio","orientation","long_edge","mode","background"],"generate"=>vec!["kind","prompt","ratio","orientation","resolution","model","source"],"undo"|"redo"=>vec!["kind","batchId"],"restore"=>vec!["kind","versionId"],"commit_edit"=>vec!["kind","edit"],"local_plan"=>vec!["kind","plan"],"pipeline"=>vec!["kind","pipeline"],"mask"=>vec!["kind","mode","radius","points"],"background"=>vec!["kind","color"],"deskew"=>vec!["kind"],"export"=>vec!["kind","format","width","height","quality","fit","background","maxBytes"],"cutout"|"white"|"center"|"trash"=>vec!["kind"],_=>return Err("UNSUPPORTED_OPERATION".into())};if op.as_object().is_none_or(|map|map.keys().any(|key|!allowed.contains(&key.as_str()))){return Err("INVALID_OPERATION_ARGUMENTS".into())}
 if kind=="export"{crate::frontend_export::validate(op)?;}
 if kind=="pipeline"{let pipeline:crate::frontend_pipeline::Pipeline=serde_json::from_value(op["pipeline"].clone()).map_err(|_|"INVALID_PIPELINE")?;pipeline.validate()?;if !pipeline.batch()||pipeline.clarification.as_ref().is_some_and(|s|!s.trim().is_empty()){return Err("INVALID_PIPELINE_MODE".into())}}
 if kind=="local_plan"{let plan:crate::assistant::Plan=serde_json::from_value(op["plan"].clone()).map_err(|_|"INVALID_PLAN")?;plan.validate()?;if plan.clarification.as_ref().is_some_and(|s|!s.trim().is_empty()){return Err("PLAN_NEEDS_CLARIFICATION".into())}}
 if kind=="commit_edit"{serde_json::from_value::<Edit>(op["edit"].clone()).map_err(|_|"INVALID_EDIT")?;}
 if kind=="mask"{crate::editor_pixels::validate_mask(op)?;}if kind=="background"{crate::editor_pixels::color(&op["color"])?;}if !op["background"].is_null(){crate::editor_pixels::color(&op["background"])?;}
 if kind=="restore"&&!op["versionId"].is_null()&&!op["versionId"].as_str().is_some_and(|id|uuid::Uuid::parse_str(id).is_ok()){return Err("INVALID_VERSION_ID".into())}
 if kind=="generate"{if !op["source"].is_null()&&!matches!(op["source"].as_str(),Some("text"|"reference")){return Err("INVALID_GENERATION_SOURCE".into())}if !op["model"].is_null()&&op["model"].as_str().is_none_or(|model|model.is_empty()||model.len()>100||!model.bytes().all(|b|b.is_ascii_alphanumeric()||b"-.".contains(&b))){return Err("INVALID_MODEL_PARAMETERS".into())}if op["prompt"].as_str().is_none_or(|text|text.trim().is_empty()||text.len()>16000)||!matches!(op["resolution"].as_str(),Some("1K"|"2K"|"4K")){return Err("INVALID_GENERATION_PARAMETERS".into())}}
 if matches!(kind,"fit_ratio"|"generate"){if !matches!(op["ratio"].as_str(),Some("1:1"|"3:2"|"4:3"|"4:5"|"16:9"))||!matches!(op["orientation"].as_str(),Some("portrait"|"landscape")){return Err("INVALID_RATIO".into())}if !op["long_edge"].is_null()&&!op["long_edge"].as_u64().is_some_and(|n|(1..=16000).contains(&n)){return Err("INVALID_SIZE".into())}if !op["mode"].is_null()&&!matches!(op["mode"].as_str(),Some("auto"|"pad"|"crop")){return Err("INVALID_FIT".into())}}
 }
 if operations.iter().enumerate().any(|(index,op)|op["kind"]=="export"&&index+1!=operations.len()){return Err("EXPORT_MUST_BE_LAST".into())}
 if operations.iter().any(|op|op["kind"]=="pipeline")&&operations.len()!=1{return Err("PIPELINE_MUST_BE_SEPARATE".into())}
 if operations.iter().any(|op|op["source"]=="text")&&operations.len()!=1{return Err("TEXT_GENERATION_MUST_BE_SEPARATE".into())}
 if operations.iter().filter(|op|op["kind"]=="generate").count()>1{return Err("ONE_GENERATION_STEP_REQUIRED".into())}
 if operations.iter().any(|op|matches!(op["kind"].as_str(),Some("undo"|"redo"|"trash"|"restore"|"commit_edit")))&&operations.len()!=1{return Err("OPERATION_MUST_BE_SEPARATE".into())}Ok(())
}
fn actual_ratio(op:&Value)->String{let ratio=op["ratio"].as_str().unwrap_or("1:1");let(a,b)=ratio.split_once(':').unwrap_or(("1","1"));let(a,b)=(a.parse::<u32>().unwrap_or(1),b.parse::<u32>().unwrap_or(1));if op["orientation"]=="portrait"{format!("{}:{}",a.min(b),a.max(b))}else{format!("{}:{}",a.max(b),a.min(b))}}
fn atomic_value(root:&Path,name:&str,value:&Value)->Res<()>{let mut file=tempfile::NamedTempFile::new_in(root).map_err(|e|e.to_string())?;file.write_all(&serde_json::to_vec(value).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;file.as_file().sync_all().map_err(|e|e.to_string())?;persist_temp(file,root.join(name))}
pub(crate) fn plan_key(args:&Value)->String{let mut value=json!({"projectId":args["projectId"],"context":args["context"],"instruction":args["instruction"]});if args["pipeline"]==true{value["pipeline"]=json!(true);value["execution"]=args["execution"].clone();value["model"]=args["model"].clone();}format!("{:x}",Sha256::digest(value.to_string()))}
pub(crate) fn cached_plan(s:&Shared,id:&str,key:&str)->Res<Option<Value>>{let root=directory(s)?;path(&root,id)?;let file=root.join(format!("{id}.plan"));if !file.exists(){return Ok(None)}let record:Value=serde_json::from_slice(&std::fs::read(file).map_err(|_|"PLAN_UNAVAILABLE")?).map_err(|_|"PLAN_UNAVAILABLE")?;if record["key"]!=key{return Err("REQUEST_ID_CONFLICT".into())}Ok(Some(record["plan"].clone()))}
pub(crate) fn cache_plan(s:&Shared,id:&str,key:&str,plan:&Value)->Res<()>{let root=directory(s)?;path(&root,id)?;atomic_value(&root,&format!("{id}.plan"),&json!({"key":key,"plan":plan}))}
fn generation_gate(s:&Shared,root:&Path,id:&str,hash:&str,project:&core::Project,ids:&[String],operations:&[Value],token:Option<&str>)->Res<Option<Value>>{
 let nested=operations.iter().find(|op|op["kind"]=="pipeline").map(|op|serde_json::from_value::<crate::frontend_pipeline::Pipeline>(op["pipeline"].clone()).map_err(|_|"INVALID_PIPELINE".to_string()).and_then(|p|p.generation_operation())).transpose()?.flatten();let op=operations.iter().find(|op|op["kind"]=="generate").or(nested.as_ref());let factor=if nested.is_some(){0.5}else{1.0};let count=if op.is_some_and(|op|op["source"]=="text"){1}else{ids.len()};let settings=crate::frontend_settings::read(s)?;let quota=crate::frontend_settings::near_quota(s,count)?;
 let estimate=if let Some(op)=op{let catalog=crate::models::load(root.parent().ok_or("TASK_STORAGE")?).0;let model=catalog.models.iter().find(|m|m.id==op["model"].as_str().unwrap_or(crate::new_product::IMAGE)).ok_or("IMAGE_MODEL_NOT_CONFIGURED")?;model.image_usd.get(op["resolution"].as_str().unwrap()).copied().flatten().map(|price|(price+model.input_usd_per_million*1000./1e6+model.text_usd_per_million*1000./1e6)*count as f64*7.2*factor)}else{None};
 if !quota&&(op.is_none()||count as u64<=settings.generation_count&&estimate.is_some_and(|price|price<=settings.cost_cny)){return Ok(None)}
 let sources=ids.iter().map(|id|{let a=project.assets.iter().find(|a|&a.id==id).unwrap();json!({"id":id,"sha256":a.sha256,"edit":a.edit,"base":a.generated_base})}).collect::<Vec<_>>();let signature=format!("{:x}",Sha256::digest(serde_json::to_vec(&json!([sources,settings,crate::frontend_settings::quota(s)?])).map_err(|e|e.to_string())?));
 let file=root.join(format!("{id}.gate"));let record=if file.exists(){let value:Value=serde_json::from_slice(&std::fs::read(&file).map_err(|_|"CONFIRMATION_UNAVAILABLE")?).map_err(|_|"CONFIRMATION_UNAVAILABLE")?;if value["estimate"]!=json!(estimate){return Err("COST_ESTIMATE_CHANGED: 参考报价已更改，请重新提交确认".into())}if value["hash"]!=hash||value["sources"]!=signature{return Err("SOURCE_CHANGED_BEFORE_CONFIRM: 图片或要求已更改，请重新提交".into())}value}else{let value=json!({"hash":hash,"sources":signature,"token":uuid::Uuid::new_v4().to_string(),"createdAt":now(),"estimate":estimate});atomic_value(root,&format!("{id}.gate"),&value)?;value};
 if let Some(token)=token{if record["token"]!=token||now().saturating_sub(record["createdAt"].as_u64().unwrap_or(0))>15*60*1000{return Err("CONFIRMATION_EXPIRED: 请重新提交确认".into())}return Ok(None)}
 let price=estimate.map(|price|format!("参考估价 ¥{price:.2}")).unwrap_or_else(||"费用尚不能确定".into());let message=if quota{format!("本次将处理 {} 张，本账号配额将达到95%以上。是否继续？",count)}else{format!("将生成 {} 张，{}。是否继续？",count,price)};Ok(Some(json!({"confirmation":{"stage":if quota{"quota"}else{"generation"},"message":message,"token":record["token"],"count":count,"estimatedCny":estimate}})))
}
fn transform(mut image:image::DynamicImage,operations:&[Value],cancel:&AtomicBool)->Res<image::DynamicImage>{
 for op in operations{if cancel.load(Ordering::Relaxed){return Err("TASK_CANCELLED".into())}match op["kind"].as_str().unwrap_or(""){
  "export"=>{},
  "local_plan"=>{let plan:crate::assistant::Plan=serde_json::from_value(op["plan"].clone()).map_err(|_|"INVALID_PLAN")?;image=crate::assistant::process(image,&plan,cancel)?;if let Some(output)=plan.output{image=core::fit(&image,output.width,output.height,output.fit=="pad",output.background);}},
  "mask"=>image=crate::editor_pixels::mask(image,op)?,
  "deskew"=>image=crate::assistant::opencv(image,"deskew",45.)?,
  "background"=>{if !image.to_rgba8().pixels().any(|p|p[3]<255){image=crate::assistant::opencv(image,"cutout",0.)?;}image=crate::assistant::process(image,&crate::assistant::Plan{summary:"背景色".into(),steps:vec![crate::assistant::Step::Flatten{background:crate::editor_pixels::color(&op["color"])?}],warnings:vec![],clarification:None,output:None},cancel)?;},
  "cutout"=>image=crate::assistant::opencv(image,"cutout",0.)?,
  "white"=>{if !image.to_rgba8().pixels().any(|p|p[3]<255){image=crate::assistant::opencv(image,"cutout",0.)?;}image=crate::assistant::process(image,&crate::assistant::Plan{summary:"白底".into(),steps:vec![crate::assistant::Step::Flatten{background:[255,255,255]}],warnings:vec![],clarification:None,output:None},cancel)?;},
  "center"=>image=crate::assistant::opencv(image,"center",0.08)?,
  "fit_ratio"=>{let ratio=op["ratio"].as_str().unwrap();let(a,b)=ratio.split_once(':').unwrap();let mut a:u32=a.parse().unwrap();let mut b:u32=b.parse().unwrap();if (op["orientation"]=="portrait"&&a>b)||(op["orientation"]=="landscape"&&a<b){std::mem::swap(&mut a,&mut b);}let edge=op["long_edge"].as_u64().unwrap_or(image.width().max(image.height()) as u64) as u32;let(width,height)=if a>=b{(edge,((edge as f64*b as f64/a as f64).round() as u32).max(1))}else{(((edge as f64*a as f64/b as f64).round() as u32).max(1),edge)};let mode=if op["mode"]=="crop"{"crop"}else{"pad"};image=crate::assistant::process(image,&crate::assistant::Plan{summary:"比例".into(),steps:vec![crate::assistant::Step::Resize{width,height,fit:mode.into(),background:if op["background"].is_null(){[255,255,255]}else{crate::editor_pixels::color(&op["background"])?}}],warnings:vec![],clarification:None,output:None},cancel)?;},
  _=>return Err("UNSUPPORTED_OPERATION".into())
 }}Ok(image)
}

#[derive(Clone)]struct Pending{s:Shared,hub:AppHandle,root:PathBuf,id:String,host:bool}
#[derive(Default)]struct Queue{pending:Vec<Pending>,active:bool}
static QUEUE:OnceLock<Mutex<Queue>>=OnceLock::new();
// Own the worker independently of the submitting async runtime; preserve per-job panic isolation.
fn enqueue(pending:Pending){let Ok(mut queue)=QUEUE.get_or_init(||Mutex::new(Queue::default())).lock()else{return};if queue.pending.iter().any(|p|p.root==pending.root&&p.id==pending.id){return}queue.pending.push(pending);publish_queue(&queue.pending);if queue.active{return}queue.active=true;drop(queue);std::thread::spawn(||{loop{let next={let Ok(mut queue)=QUEUE.get().unwrap().lock()else{return};if queue.pending.is_empty(){queue.active=false;return}let index=queue.pending.iter().position(|p|p.host).unwrap_or(0);let next=queue.pending.remove(index);publish_queue(&queue.pending);next};let _=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||run(next)));}});}
fn publish_queue(pending:&[Pending]){let mut sorted=pending.iter().collect::<Vec<_>>();sorted.sort_by_key(|p|!p.host);for(index,p)in sorted.iter().enumerate(){if let Ok(job)=read(&p.root,&p.id){let mut task=view(&job);task["queuePosition"]=json!(index);let _=p.hub.emit("task.queue",task);}}}
fn emit(job:&Job,hub:&AppHandle,root:&Path){let event=if job.state=="failed"{"task.failed"}else if terminal(&job.state){"task.done"}else{"task.progress"};let _=hub.emit(event,task_view(root,job));}
