 let child=crate::hybrid::start(&s,job.project_id.clone(),job.items.iter().map(|i|i.id.clone()).collect(),pipeline.summary.clone(),recipe.clone(),output.to_string_lossy().into(),true,job.id.clone())?;if serde_json::to_value(&child.recipe).ok()!=serde_json::to_value(&recipe).ok(){return Err("REQUEST_ID_CONFLICT".into())}
