 let result=if model==crate::new_product::IMAGE&&input.is_some(){crate::transport::runtime::block_on(crate::new_product::generate_reference(input.unwrap(),op["prompt"].as_str().unwrap(),op["resolution"].as_str().unwrap(),&actual_ratio(op)))}else{let input=input.map(core::png).transpose()?;crate::transport::runtime::block_on(crate::image_provider::generate(model,op["prompt"].as_str().unwrap(),input,op["resolution"].as_str().unwrap(),&actual_ratio(op)))}?;
