 #[test]fn text_generation_without_saved_pixels_is_uncertain_and_never_resubmitted(){let(_temp,s,pid,_)=setup();let root=directory(&s).unwrap();let id=uuid::Uuid::new_v4().to_string();let job=Job{id:id.clone(),project_id:pid.clone(),request_hash:"unknown-outcome".into(),operations:vec![json!({"kind":"generate","source":"text"})],items:vec![Item{id:uuid::Uuid::new_v4().to_string(),before:Snapshot{base:None,edit:Edit::default(),trashed:true},after:None,state:"submitted".into(),error:None}],state:"running".into(),created_at:now(),started_at:None,updated_at:now(),host:true,undone:false};save(&root,&job).unwrap();run(Pending{s:s.clone(),hub:hub(),root:root.clone(),id:id.clone(),host:true});let result=read(&root,&id).unwrap();assert_eq!(result.items[0].state,"uncertain");assert_eq!(locked(&s).unwrap().load(&pid).unwrap().assets.len(),1);}
 #[test]fn text_request_has_one_output_cost_gate_with_empty_scope_and_no_placeholder(){let(_temp,s,pid,mut context)=setup();let op=json!({"kind":"generate","source":"text","model":"GPT-Image-2.5-Flare","prompt":"fixture only","ratio":"16:9","orientation":"portrait","resolution":"1K"});let id=uuid::Uuid::new_v4().to_string();let mut args=json!({"projectId":pid,"clientRequestId":id,"context":context,"operations":[op]});assert!(execute(s.clone(),hub(),args.clone(),true).is_err());context["selected"]=json!([]);context["fileNames"]=json!([]);context["filteredCount"]=json!(0);context["resolvedTarget"]=json!({"source":"filter","ids":[]});args["context"]=context;let result=execute(s.clone(),hub(),args,true).unwrap();assert_eq!(result["confirmation"]["count"],1);assert!(result.get("task").is_none());assert_eq!(locked(&s).unwrap().load(&pid).unwrap().assets.len(),1);assert!(list(&s).unwrap().is_empty());}
 #[test]fn settings_change_generation_and_quota_gates_without_provider_requests(){let(_temp,s,pid,context)=setup();let root=directory(&s).unwrap();let p=locked(&s).unwrap().load(&pid).unwrap();let ids=context["selected"].as_array().unwrap().iter().map(|id|id.as_str().unwrap().to_string()).collect::<Vec<_>>();let operations=vec![json!({"kind":"generate","prompt":"fixture","ratio":"1:1","orientation":"landscape","resolution":"1K"})];let id=uuid::Uuid::new_v4().to_string();assert!(generation_gate(&s,&root,&id,"fixture",&p,&ids,&operations,None).unwrap().is_none());crate::frontend_settings::patch(&s,&json!({"costCny":0.01})).unwrap();assert!(generation_gate(&s,&root,&id,"fixture",&p,&ids,&operations,None).unwrap().is_some());crate::frontend_settings::patch(&s,&json!({"quotas":{"host":1}})).unwrap();let id=uuid::Uuid::new_v4().to_string();let result=generation_gate(&s,&root,&id,"local",&p,&ids,&[json!({"kind":"center"})],None).unwrap().unwrap();assert_eq!(result["confirmation"]["stage"],"quota");assert!(generation_gate(&s,&root,&id,"local",&p,&ids,&[json!({"kind":"center"})],result["confirmation"]["token"].as_str()).unwrap().is_none());}
 #[tokio::test]async fn editor_mask_commit_and_undo_preserve_source_and_history(){let(_temp,s,pid,context)=setup();let aid=context["selected"][0].as_str().unwrap();let original=locked(&s).unwrap().original_preview(&pid,aid).unwrap();let id=uuid::Uuid::new_v4().to_string();execute(s.clone(),hub(),json!({"projectId":pid,"context":context,"clientRequestId":id,"operations":[{"kind":"mask","mode":"erase","radius":0.1,"points":[[0.2,0.5],[0.8,0.5]]}]}),true).unwrap();assert_eq!(done(&s,&id).await.state,"done");let p=locked(&s).unwrap().load(&pid).unwrap();let image=locked(&s).unwrap().source(&p,aid).unwrap().to_rgba8();assert_eq!(image.get_pixel(80,45)[3],0);assert_eq!(image.get_pixel(80,0)[3],255);assert_eq!(p.assets[0].versions.len(),1);restore_batch(&s,&hub(),&pid,Some(&id),false).unwrap();assert_eq!(locked(&s).unwrap().original_preview(&pid,aid).unwrap(),original);let next=uuid::Uuid::new_v4().to_string();let mut edit=Edit::default();edit.crop=Some([0.,0.,0.5,1.]);execute(s.clone(),hub(),json!({"projectId":pid,"context":context,"clientRequestId":next,"operations":[{"kind":"commit_edit","edit":edit}]}),true).unwrap();assert_eq!(done(&s,&next).await.state,"done");let p=locked(&s).unwrap().load(&pid).unwrap();assert_eq!(p.assets[0].versions.len(),2);assert_eq!(p.assets[0].edit.crop,Some([0.,0.,0.5,1.]));restore_batch(&s,&hub(),&pid,Some(&next),false).unwrap();assert_eq!(locked(&s).unwrap().load(&pid).unwrap().assets[0].edit.crop,None);assert_eq!(locked(&s).unwrap().original_preview(&pid,aid).unwrap(),original);}
 #[test]fn ratio_padding_respects_selected_color_without_enlarging_long_edge(){let source=image::DynamicImage::ImageRgba8(image::RgbaImage::from_pixel(160,90,image::Rgba([80,120,160,255])));let op=json!({"kind":"fit_ratio","ratio":"1:1","orientation":"landscape","background":[12,34,56],"mode":"pad"});validate_operations(&[op.clone()]).unwrap();let output=transform(source,&[op],&AtomicBool::new(false)).unwrap().to_rgba8();assert_eq!(output.dimensions(),(160,160));assert_eq!(output.get_pixel(0,0).0,[12,34,56,255]);assert_eq!(output.get_pixel(80,80).0,[80,120,160,255]);}
 #[tokio::test]async fn explicit_export_size_quality_and_background_leave_source_versions_untouched(){let(_temp,s,pid,context)=setup();let aid=context["selected"][0].as_str().unwrap();let before=locked(&s).unwrap().load(&pid).unwrap();let id=uuid::Uuid::new_v4().to_string();let result=execute(s.clone(),hub(),json!({"projectId":pid,"context":context,"clientRequestId":id,"operations":[{"kind":"export","format":"jpeg","width":80,"height":100,"quality":37,"fit":"crop","background":[230,220,210],"maxBytes":0}]}),true).unwrap();assert_eq!(result["task"]["undoable"],false);assert_eq!(done(&s,&id).await.state,"done");let bytes=crate::frontend_output::result(&s,&id,aid).unwrap();let image=image::load_from_memory(&bytes).unwrap();assert_eq!((image.width(),image.height()),(80,100));let view=list(&s).unwrap().into_iter().find(|t|t["id"]==id).unwrap();assert_eq!(view["outputs"][0]["quality"],37);assert_eq!(view["quotaUnits"],0);let after=locked(&s).unwrap().load(&pid).unwrap();assert_eq!(before.assets[0].sha256,after.assets[0].sha256);assert_eq!(serde_json::to_value(&before.assets[0].edit).unwrap(),serde_json::to_value(&after.assets[0].edit).unwrap());assert_eq!(before.assets[0].versions.len(),after.assets[0].versions.len());let invalid=uuid::Uuid::new_v4().to_string();assert!(execute(s.clone(),hub(),json!({"projectId":pid,"context":context,"clientRequestId":invalid,"operations":[{"kind":"export","width":80}]}),true).is_err());assert!(!directory(&s).unwrap().join(format!("{invalid}.json")).exists());}
 async fn done(s:&Shared,id:&str)->Job{for _ in 0..1500{let job=read(&directory(s).unwrap(),id).unwrap();if terminal(&job.state){return job}tokio::time::sleep(std::time::Duration::from_millis(10)).await;}panic!("operation did not complete")}
 #[test]fn direct_ratio_is_persistent_idempotent_and_batch_undo_redo_preserves_original(){crate::transport::runtime::block_on(async{
  let(_temp,s,pid,context)=setup();let aid=context["selected"][0].as_str().unwrap();let before=locked(&s).unwrap().original_preview(&pid,aid).unwrap();let id=uuid::Uuid::new_v4().to_string();let args=json!({"projectId":pid,"context":context,"clientRequestId":id,"operations":[{"kind":"fit_ratio","ratio":"16:9","orientation":"portrait","mode":"pad"}]});let first=execute(s.clone(),hub(),args.clone(),true).unwrap();assert_eq!(first["task"]["id"],id);let job=done(&s,&id).await;assert_eq!(job.state,"done");execute(s.clone(),hub(),args,true).unwrap();let p=locked(&s).unwrap().load(&pid).unwrap();assert_eq!(p.assets[0].versions.len(),1);let image=locked(&s).unwrap().source(&p,aid).unwrap();assert_eq!((image.width(),image.height()),(90,160));
  restore_batch(&s,&hub(),&pid,Some(&id),false).unwrap();let p=locked(&s).unwrap().load(&pid).unwrap();assert_eq!(p.assets[0].generated_base,None);assert_eq!(locked(&s).unwrap().original_preview(&pid,aid).unwrap(),before);assert_eq!(p.assets[0].versions.len(),1);restore_batch(&s,&hub(),&pid,Some(&id),true).unwrap();assert!(locked(&s).unwrap().load(&pid).unwrap().assets[0].generated_base.is_some());
 });}
