 #[tokio::test]async fn generation_gate_is_bound_to_request_and_sources_before_any_provider(){
  let(temp,s,pid,mut context)=setup();let files=(0..4).map(|i|{let path=temp.path().join(format!("angle-{i}.png"));image::RgbaImage::from_pixel(8,8,image::Rgba([30+i,90,110,255])).save(&path).unwrap();path.to_string_lossy().to_string()}).collect::<Vec<_>>();let p=locked(&s).unwrap().import(&pid,files,&AtomicBool::new(false),|_,_|{}).unwrap().project;let ids=p.assets.iter().map(|a|a.id.clone()).collect::<Vec<_>>();context["selected"]=json!(ids);context["resolvedTarget"]["ids"]=json!(ids);context["fileNames"]=json!(p.assets.iter().map(|a|a.name.clone()).collect::<Vec<_>>());context["filteredCount"]=json!(5);
  let id=uuid::Uuid::new_v4().to_string();let operations=vec![json!({"kind":"generate","prompt":"Nordic still life; preserve the product","ratio":"4:5","orientation":"portrait","resolution":"1K"})];let input=json!({"projectId":pid,"context":context,"clientRequestId":id,"operations":operations});let result=execute(s.clone(),hub(),input.clone(),true).unwrap();assert_eq!(result["confirmation"]["count"],5);assert!(!path(&directory(&s).unwrap(),&id).unwrap().exists());let mut wrong=input;wrong["confirmToken"]=json!("wrong");assert!(execute(s.clone(),hub(),wrong,true).is_err());
  let root=directory(&s).unwrap();let record:Value=serde_json::from_slice(&std::fs::read(root.join(format!("{id}.gate"))).unwrap()).unwrap();assert!(generation_gate(&s,&root,&id,record["hash"].as_str().unwrap(),&p,&ids,&operations,result["confirmation"]["token"].as_str()).unwrap().is_none());let mut changed=p;changed.assets[0].edit.exposure=0.5;assert!(generation_gate(&s,&root,&id,record["hash"].as_str().unwrap(),&changed,&ids,&operations,result["confirmation"]["token"].as_str()).is_err());
 }
