 #[tokio::test]async fn saved_generation_does_not_overwrite_newer_edits_during_recovery(){
  let(_temp,s,pid,_context)=setup();let root=directory(&s).unwrap();let p=locked(&s).unwrap().load(&pid).unwrap();let aid=p.assets[0].id.clone();let id=uuid::Uuid::new_v4().to_string();let before=Snapshot::of(&p.assets[0]);let image=image::DynamicImage::new_rgba8(40,60);locked(&s).unwrap().save_generated(&pid,&aid,&image,json!({"operationTask":id})).unwrap();let mut edit=p.assets[0].edit.clone();edit.exposure=0.3;locked(&s).unwrap().commit(&pid,&aid,edit).unwrap();let job=Job{id:id.clone(),project_id:pid.clone(),request_hash:"recovery".into(),operations:vec![json!({"kind":"generate","prompt":"preserve product","ratio":"1:1","orientation":"landscape","resolution":"1K"})],items:vec![Item{id:aid.clone(),before,after:None,state:"submitted".into(),error:None}],state:"running".into(),created_at:now(),started_at:Some(now()),updated_at:now(),host:true,undone:false};save(&root,&job).unwrap();run(Pending{s:s.clone(),hub:hub(),root:root.clone(),id:id.clone(),host:true});let recovered=read(&root,&id).unwrap();assert_eq!(recovered.state,"done");assert!(recovered.items[0].error.as_deref().unwrap().contains("当前图片未被替换"));let actual=locked(&s).unwrap().load(&pid).unwrap();assert_eq!(actual.assets[0].edit.exposure,0.3);assert_eq!(actual.assets[0].versions.len(),2);assert_eq!(actual.assets[0].generated_base,None);
 }
