 #[test]fn local_cutout_changes_the_alpha_and_white_actually_removes_opaque_background(){
  let mut image=image::RgbaImage::from_pixel(200,240,image::Rgba([170,130,90,255]));for y in 50..190{for x in 65..135{image.put_pixel(x,y,image::Rgba([235,240,245,255]));}}
  let source=image::DynamicImage::ImageRgba8(image);let cut=transform(source.clone(),&[json!({"kind":"cutout"})],&AtomicBool::new(false)).unwrap().to_rgba8();assert_eq!(cut.get_pixel(0,0)[3],0);assert_eq!(cut.get_pixel(100,100)[3],255);
  let white=transform(source,&[json!({"kind":"white"})],&AtomicBool::new(false)).unwrap().to_rgba8();assert_eq!(white.get_pixel(0,0).0,[255,255,255,255]);assert_eq!(&white.get_pixel(100,100).0[..3],&[235,240,245]);
 }
